#include <algorithm>
#include <vector>

struct Row { int team; int score; char name; };

void Rank(std::vector<Row>& rows) {
  std::stable_sort(rows.begin(), rows.end(),
      [](const Row& a, const Row& b) { return a.team < b.team; });
  std::stable_sort(rows.begin(), rows.end(),
      [](const Row& a, const Row& b) { return a.score > b.score; });
}
